package com.grad.ventora.about.service.impl;
import com.grad.ventora.about.dto.*; import com.grad.ventora.about.entity.*; import com.grad.ventora.about.repository.AboutPageRepository; import com.grad.ventora.about.service.IAboutPageService; import com.grad.ventora.exception.exceptions.ResourceNotFoundException;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional
public class AboutPageServiceImpl implements IAboutPageService {
 private final AboutPageRepository repository;
 @Override @Transactional(readOnly=true) public AboutPageResponse getPublished(){ AboutPage p=repository.findFirstByPublishedTrueOrderByIdAsc().orElseThrow(()->new ResourceNotFoundException("Published About page not found")); return toResponse(p); }
 @Override @Transactional(readOnly=true) public AboutPageResponse getDraft(){ AboutPage p=repository.findFirstByOrderByIdAsc().orElseThrow(()->new ResourceNotFoundException("About page not found")); return toResponse(p); }
 @Override public AboutPageResponse save(AboutPageRequest r){ AboutPage p=repository.findFirstByOrderByIdAsc().orElseGet(AboutPage::new);
  p.setHeroTitle(r.heroTitle()); p.setHeroDescription(r.heroDescription()); p.setHeroValueOne(r.heroValueOne()); p.setHeroValueTwo(r.heroValueTwo()); p.setHeroValueThree(r.heroValueThree()); p.setHeroValueFour(r.heroValueFour());
  p.setStoryTitle(r.storyTitle()); p.setStoryDescription(r.storyDescription()); p.setStoryVideoUrl(r.storyVideoUrl()); p.setStoryVideoDuration(r.storyVideoDuration()); p.setMissionTitle(r.missionTitle()); p.setMissionDescription(r.missionDescription()); p.setVisionTitle(r.visionTitle()); p.setVisionDescription(r.visionDescription()); if(r.published()!=null)p.setPublished(r.published());
  p.getStatistics().clear(); if(r.statistics()!=null) for(var x:r.statistics()){AboutStatistic e=new AboutStatistic();e.setAboutPage(p);e.setValue(x.value());e.setLabel(x.label());e.setDisplayOrder(x.displayOrder()==null?0:x.displayOrder());p.getStatistics().add(e);}
  p.getValues().clear(); if(r.values()!=null) for(var x:r.values()){AboutValue e=new AboutValue();e.setAboutPage(p);e.setTitle(x.title());e.setDescription(x.description());e.setDisplayOrder(x.displayOrder()==null?0:x.displayOrder());p.getValues().add(e);}
  p.getTeamMembers().clear(); if(r.teamMembers()!=null) for(var x:r.teamMembers()){AboutTeamMember e=new AboutTeamMember();e.setAboutPage(p);e.setName(x.name());e.setRole(x.role());e.setPhotoUrl(x.photoUrl());e.setLinkedInUrl(x.linkedInUrl());e.setDisplayOrder(x.displayOrder()==null?0:x.displayOrder());p.getTeamMembers().add(e);}
  return toResponse(repository.save(p)); }
 private AboutPageResponse toResponse(AboutPage p){return new AboutPageResponse(p.getId(),p.getHeroTitle(),p.getHeroDescription(),p.getHeroValueOne(),p.getHeroValueTwo(),p.getHeroValueThree(),p.getHeroValueFour(),p.getStoryTitle(),p.getStoryDescription(),p.getStoryVideoUrl(),p.getStoryVideoDuration(),p.getMissionTitle(),p.getMissionDescription(),p.getVisionTitle(),p.getVisionDescription(),p.isPublished(),p.getStatistics().stream().map(x->new AboutPageResponse.StatisticResponse(x.getId(),x.getValue(),x.getLabel(),x.getDisplayOrder())).toList(),p.getValues().stream().map(x->new AboutPageResponse.ValueResponse(x.getId(),x.getTitle(),x.getDescription(),x.getDisplayOrder())).toList(),p.getTeamMembers().stream().map(x->new AboutPageResponse.TeamMemberResponse(x.getId(),x.getName(),x.getRole(),x.getPhotoUrl(),x.getLinkedInUrl(),x.getDisplayOrder())).toList(),p.getCreatedAt(),p.getUpdatedAt());}
}
